package ro.leo.visual;
import android.app.*;import android.content.*;import android.database.Cursor;import android.graphics.*;import android.os.*;import android.provider.ContactsContract;import android.provider.ContactsContract.CommonDataKinds.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;

/** Short keypad/UI checks with synthetic contacts, images and drafts; no transmission. */
public final class FiveAppsUiTests extends Instrumentation {
 private int count;private void check(boolean b,String s){if(!b)throw new AssertionError(s);count++;}
 private Object get(Object a,String n)throws Exception{java.lang.reflect.Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(a);}
 private void set(Object a,String n,Object v)throws Exception{java.lang.reflect.Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);f.set(a,v);}
 private void invoke(final Object a,String name,Class<?>[] types,final Object...args)throws Exception{final java.lang.reflect.Method m=a.getClass().getDeclaredMethod(name,types);m.setAccessible(true);runOnMainSync(new Runnable(){public void run(){try{m.invoke(a,args);}catch(Exception e){throw new RuntimeException(e);}}});}
 private Activity open(Class<?> cls){return startActivitySync(new Intent(getTargetContext(),cls).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP));}
 private void close(final Activity a){if(a!=null)runOnMainSync(new Runnable(){public void run(){a.finish();}});waitForIdleSync();}
 private void capture(String name)throws Exception{SystemClock.sleep(200);Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),"five-"+name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}finally{b.recycle();}}
 public void onCreate(Bundle b){start();}
 public void onStart(){Context c=getTargetContext();Bundle out=new Bundle();File folder=new File(c.getExternalFilesDir(null),"five-local-ui-"+UUID.randomUUID());folder.mkdirs();File a=new File(folder,"a.txt"),b=new File(folder,"b.txt"),picture=new File(folder,"local.png"),backup=new File(folder,"fixture.leo-backup.json");long raw=-1;Activity activity=null;String target="202555"+(SystemClock.elapsedRealtime()%100000000L);String draftId=null;try{
  try(FileOutputStream f=new FileOutputStream(a)){f.write("local A".getBytes("UTF-8"));}try(FileOutputStream f=new FileOutputStream(b)){f.write("local B".getBytes("UTF-8"));}Bitmap image=Bitmap.createBitmap(400,200,Bitmap.Config.RGB_565);Canvas canvas=new Canvas(image);canvas.drawColor(0xff12558b);Paint p=new Paint();p.setColor(0xffffc340);canvas.drawRect(0,0,180,200,p);p.setColor(Color.WHITE);p.setTextSize(28);canvas.drawText("LEO LOCAL",190,110,p);try(FileOutputStream f=new FileOutputStream(picture)){image.compress(Bitmap.CompressFormat.PNG,100,f);}ByteArrayOutputStream photo=new ByteArrayOutputStream();image.compress(Bitmap.CompressFormat.JPEG,70,photo);image.recycle();
  ContentValues values=new ContentValues();values.put(ContactsContract.RawContacts.AGGREGATION_MODE,ContactsContract.RawContacts.AGGREGATION_MODE_DISABLED);raw=ContentUris.parseId(c.getContentResolver().insert(ContactsContract.RawContacts.CONTENT_URI,values));ContentValues name=new ContentValues();name.put(ContactsContract.Data.RAW_CONTACT_ID,raw);name.put(ContactsContract.Data.MIMETYPE,StructuredName.CONTENT_ITEM_TYPE);name.put(StructuredName.DISPLAY_NAME,"LEO LOCAL UI");c.getContentResolver().insert(ContactsContract.Data.CONTENT_URI,name);ContactBook.saveNumber(c,raw,-1,"+12025550131",Phone.TYPE_MOBILE);ContactBook.saveNumber(c,raw,-1,"+12025550132",Phone.TYPE_WORK);ContactBook.photo(c,raw,photo.toByteArray());
  activity=open(ContactsActivity.class);final Activity contacts=activity;runOnMainSync(new Runnable(){public void run(){try{set(contacts,"filter","LEO LOCAL UI");}catch(Exception e){throw new RuntimeException(e);}}});invoke(activity,"load",new Class<?>[]{});for(int i=0;i<50&&((ArrayList)get(activity,"entries")).size()!=1;i++)SystemClock.sleep(100);ArrayList rows=(ArrayList)get(activity,"entries");check(rows.size()==1,"one row for two numbers");Object entry=rows.get(0);invoke(activity,"detail",new Class<?>[]{entry.getClass()},entry);SystemClock.sleep(400);check(((TextView)((LeoActivity)contacts).root.getChildAt(0)).getText().toString().contains("LEO LOCAL UI"),"contact detail survives pending list queries");capture("contact");invoke(activity,"numbers",new Class<?>[]{entry.getClass()},entry);capture("contact-numbers");close(activity);activity=null;
  activity=open(FilesActivity.class);set(activity,"base",folder);invoke(activity,"browse",new Class<?>[]{File.class},folder);for(int i=0;i<50&&((ArrayList)get(activity,"entries")).size()<3;i++)SystemClock.sleep(100);sendKeyDownUpSync(KeyEvent.KEYCODE_5);SystemClock.sleep(200);sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_DOWN);sendKeyDownUpSync(KeyEvent.KEYCODE_5);SystemClock.sleep(300);check(((Set)get(activity,"marked")).size()==2,"key 5 marks two files");capture("files");
  ActivityMonitor monitor=addMonitor(GalleryActivity.class.getName(),null,false);invoke(activity,"open",new Class<?>[]{File.class},picture);Activity gallery=monitor.waitForActivityWithTimeout(5000);removeMonitor(monitor);check(gallery!=null,"image file opens in Leo Gallery");close(activity);activity=gallery;for(int i=0;i<50&&get(gallery,"photo")==null;i++)SystemClock.sleep(100);check(get(gallery,"photo")!=null,"image decoded");sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_RIGHT);check((Integer)get(gallery,"zoom")==2&&((Float)get(gallery,"panX"))<0,"2x zoom pans without changing image");capture("gallery");close(activity);activity=null;
  activity=startActivitySync(new Intent(c,MessagesActivity.class).putExtra("number",target).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP));final EditText body=(EditText)get(activity,"body");runOnMainSync(new Runnable(){public void run(){char[] chars=new char[161];Arrays.fill(chars,'A');body.setText(new String(chars));}});capture("sms-counter");close(activity);activity=null;try(DraftStore store=new DraftStore(c)){DraftStore.Draft draft=store.forNumber(target);check(draft!=null&&draft.body.length()==161,"draft saved locally without sending");if(draft!=null){draftId=draft.id;store.remove(draft.id);}}
  JSONObject data=BackupEngine.snapshot(c);data.put("wallpaper",JSONObject.NULL);data.put("notes",new JSONArray().put(new JSONObject().put("id","ui-fixture").put("body","Notiță demonstrativă")));for(String group:new String[]{"dialer-favorites","speed-dial","notes-draft"})data.getJSONObject("preferences").put(group,new JSONObject());data.put("dictionary",new JSONObject().put("words","test\t1\n").put("mode",0));BackupEngine.write(backup,BackupEngine.archive(data));activity=open(BackupActivity.class);SystemClock.sleep(300);invoke(activity,"preview",new Class<?>[]{File.class},backup);for(int i=0;i<50&&(Boolean)get(activity,"busy");i++)SystemClock.sleep(100);check(!((Boolean)get(activity,"busy")),"backup preview finished");capture("backup");close(activity);activity=null;out.putString("result","PASS "+count+" UI/keypad checks; screenshots use local fixtures");
 }catch(Throwable e){out.putString("error",android.util.Log.getStackTraceString(e));}finally{close(activity);if(raw>=0)c.getContentResolver().delete(ContentUris.withAppendedId(ContactsContract.RawContacts.CONTENT_URI,raw),null,null);try(DraftStore store=new DraftStore(c)){DraftStore.Draft d=store.forNumber(target);if(d!=null)store.remove(d.id);}a.delete();b.delete();picture.delete();backup.delete();folder.delete();}finish(out.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,out);}
}
